1	<!doctype html>
2	<html><head><meta charset="utf-8"><title>Screen 05 full track test</title>
3	<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no"><!-- [controls] phones: 1 CSS px = 1 canvas px, no pinch-zoom while swiping -->
4	<style>
5	html,body{margin:0;background:#000;overflow:hidden;font-family:system-ui,sans-serif}canvas{display:block}
6	#hud{position:fixed;left:0;right:0;top:10px;display:flex;flex-direction:column;align-items:center;gap:8px;pointer-events:none}
7	.bar{display:flex;gap:28px;align-items:center;background:linear-gradient(#7b2bbf,#4a1386);border:2px solid #d9a7ff;border-radius:30px;padding:6px 22px;color:#fff;font-weight:800;font-size:22px;box-shadow:0 2px 8px #0006}
8	.title{background:#5a1aa0e0;border:2px solid #f2c14e;border-radius:20px;padding:4px 18px;color:#fff;font-weight:800;font-style:italic;font-size:17px;letter-spacing:.5px}
9	</style>
10	<script type="importmap">{"imports":{"three":"./node_modules/three/build/three.module.js","three/addons/":"./node_modules/three/examples/jsm/","@sparkjsdev/spark":"./node_modules/@sparkjsdev/spark/dist/spark.module.js"}}</script>
11	</head><body>
12	<div id="hud"><div class="bar"><span>&#10084;&#65039; 5/5</span><span id="coins">&#129689; 1,420</span></div><div class="title">05 &middot; FLOW INTO THE CURRENT</div></div>
13	<script type="module">
14	import * as THREE from 'three';
15	import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
16	import { SplatMesh, SparkRenderer } from '@sparkjsdev/spark';
17	import { createWaterFlow } from './waterflow.js'; // [waterflow]
18	import { installControls } from './controls.js'; // [controls]
19	const q = new URLSearchParams(location.search);
20	const W = +(q.get('w') ?? 540), H = +(q.get('h') ?? 960);
21	const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
22	renderer.setPixelRatio(1); renderer.setSize(W, H); document.body.appendChild(renderer.domElement);
23	renderer.toneMapping = THREE.NeutralToneMapping; renderer.toneMappingExposure = 0.86;
24	const SC = await (await fetch('scene05.json')).json();
25	const TD = q.get('trk') ?? 'track_w/'; // [track] rebuilt pieces (tools/build_track_w.py); ?trk=track/ = the previous pieces
26	const TR = await (await fetch(TD + 'track.json')).json();
27	const scene = new THREE.Scene();
28	// QA: ?bg=%2300ff00 paints the clear colour (normally black) so any hole left in the splat track shows up in a test colour
29	if (q.get('bg')) scene.background = new THREE.Color(q.get('bg'));
30	const camera = new THREE.PerspectiveCamera(SC.cam.fov, W / H, 0.01, 200);
31	const spark = new SparkRenderer({ renderer }); scene.add(spark);
32	const flip = (m) => { m.quaternion.set(1, 0, 0, 0); return m; };
33	
34	// ---------- track: start piece, alternating sharp sections (bay / mirrored bay), light sections far away, tunnel end ----------
35	const L2 = !q.get('trk'); // [track] very distant copies use the 35 % pieces (*_lo2)
36	// [track] Android splat budget: the start piece is split along the tunnel (tools/split_near.py, u = 1.25): near_b = its front part,
37	// nearA = its rear part (253k splats from far behind the start camera up to u = 1.25). nearA is hidden only when ALL of it is behind
38	// the camera (exact test on its convex hull + the largest splat's reach), so nothing on screen changes. ?nosplit=1 = one piece.
39	const NA = L2 && !q.get('nosplit') ? await (await fetch(TD + 'near_a_hull.json')).json() : null;
40	const near = flip(new SplatMesh({ url: TD + (NA ? 'near_b.ply' : 'near.ply') })); scene.add(near);
41	const nearA = NA ? flip(new SplatMesh({ url: TD + 'near_a.ply' })) : null; if (nearA) scene.add(nearA);
42	const NAH = NA ? NA.hull.map((p) => new THREE.Vector3(...p)) : null, naF = new THREE.Vector3(), naD = new THREE.Vector3();
43	const far = flip(new SplatMesh({ url: TD + 'far.ply' })); scene.add(far);
44	const src = { hi: new SplatMesh({ url: TD + 'bay.ply' }), him: new SplatMesh({ url: TD + 'bay_m.ply' }), lo: new SplatMesh({ url: TD + 'bay_lo.ply' }), lom: new SplatMesh({ url: TD + 'bay_m_lo.ply' }),
45	  ...(L2 ? { lo2: new SplatMesh({ url: TD + 'bay_lo2.ply' }), lom2: new SplatMesh({ url: TD + 'bay_m_lo2.ply' }) } : {}) };
46	await Promise.all([near.initialized, far.initialized, ...Object.values(src).map((m) => m.initialized)]);
47	const DV = new THREE.Vector3(...TR.D), AX = new THREE.Vector3(...TR.ax), N = new THREE.Vector3(...TR.n), DU = DV.dot(AX);
48	// [end] round 32c: EXT more copies continue the tunnel BEYOND the path end (visual only, Benny never reaches them), so the end light stays
49	// small and far away (approved-like) until the ending transition instead of becoming a big flat disc close ahead. ?endext=0 = none
50	const EXT = L2 ? +(q.get('endext') ?? 5) : 0, NT = TR.N + EXT;
51	const OFF = (k) => (k <= TR.N ? new THREE.Vector3(...TR.offsets[k - 1]) : DV.clone().multiplyScalar(k)); // offsets[k-1] = k * D exactly
52	const tiles = [];
53	for (let k = 1; k <= NT; k++) {
54	  const mir = q.get('nomirror') ? false : k % 2 === 1;
55	  const hi = flip(new SplatMesh({ packedSplats: (mir ? src.him : src.hi).packedSplats })), lo = flip(new SplatMesh({ packedSplats: (mir ? src.lom : src.lo).packedSplats }));
56	  const lo2 = L2 ? flip(new SplatMesh({ packedSplats: (mir ? src.lom2 : src.lo2).packedSplats })) : null;
57	  for (const m of [hi, lo, lo2]) if (m) { m.position.copy(OFF(k)); m.visible = false; scene.add(m); }
58	  tiles.push({ k, hi, lo, lo2 });
59	}
60	const WF = q.get('noflow') ? null : createWaterFlow({ TR, SC, meshes: [near, nearA, far, ...tiles.flatMap((t) => [t.hi, t.lo, t.lo2])].filter(Boolean), far, kmax: L2 ? NT + 1 : null, amp: +(q.get('flowamp') ?? 1), speed: +(q.get('flowspeed') ?? 0.9) }); // [waterflow]
61	// [track] backing shells (tools/build_backing.py): 4 cm behind each piece's splats, in the piece's own local colours; they only show
62	// where the splats leave a hole (the wall bases at the section joints), instead of the black clear colour. ?noback=1 = off
63	const BK = {};
64	if (L2 && !q.get('noback')) for (const nm of ['near', 'bay', 'bay_m']) { const j = await (await fetch(TD + 'backing_' + nm + '.json')).json(); const g = new THREE.BufferGeometry();
65	  g.setAttribute('position', new THREE.Float32BufferAttribute(j.pos, 3)); g.setAttribute('color', new THREE.Float32BufferAttribute(j.col, 3)); g.setIndex(j.idx); BK[nm] = g; }
66	const bkMat = q.get('bkdebug') ? new THREE.MeshBasicMaterial({ color: 0xff0000, side: THREE.DoubleSide }) : new THREE.MeshBasicMaterial({ vertexColors: true, toneMapped: false, side: THREE.DoubleSide });
67	const nearBk = BK.near ? new THREE.Mesh(BK.near, bkMat) : null; if (nearBk) scene.add(nearBk);
68	for (const t of tiles) if (BK.bay) { t.bk = new THREE.Mesh(q.get('nomirror') || t.k % 2 === 0 ? BK.bay : BK.bay_m, bkMat); t.bk.position.copy(OFF(t.k)); t.bk.visible = false; scene.add(t.bk); }
69	let kcNow = -99;
70	// [track] the tunnel runs on for FARK sections and ends in the painting's bright golden light (a soft glow behind the splats)
