+const FOCPX = 768 / Math.tan(K.fov * Math.PI / 360);
+const camR = new THREE.Vector3(1, 0, 0).applyQuaternion(camQ0), camU = new THREE.Vector3(0, 1, 0).applyQuaternion(camQ0), camF = new THREE.Vector3(0, 0, -1).applyQuaternion(camQ0);
