+const coreTex = (() => { const c = document.createElement('canvas'); c.width = c.height = 256; const g = c.getContext('2d'); const gr = g.createRadialGradient(128, 128, 0, 128, 128, 128);
+  for (const [o, col] of [[0, 'rgba(255,255,245,1)'], [0.12, 'rgba(255,245,200,0.95)'], [0.3, 'rgba(255,215,140,0.55)'], [0.6, 'rgba(255,170,120,0.15)'], [1, 'rgba(255,150,120,0)']]) gr.addColorStop(o, col);
