const TS = TR.trail_s, TEND = TS[TS.length - 1];
const S_END = (() => {
  if (!TR.XB || !TR.offsets || !TR.trail) return TEND;
  const o = TR.offsets[TR.N - 1], X = [TR.XB[0] + o[0], TR.XB[1] + o[1], TR.XB[2] + o[2]];
